export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed);
  const g = Number(inputs.gravity);
  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);
  const duration = (2 * u) / g;
  const t = Math.min(Math.max(0, Number(time)), duration);

  const tossedHeight = u * t - 0.5 * g * t * t;
  const tossedVelocity = u - g * t;
  const tossedAcceleration = -g;

  let dropHeight = apexHeight;
  let dropVelocity = 0;
  let dropAcceleration = 0;
  let gateOpen = false;

  if (t >= apexTime) {
    gateOpen = true;
    const tDrop = t - apexTime;
    dropHeight = apexHeight - 0.5 * g * tDrop * tDrop;
    dropVelocity = -g * tDrop;
    dropAcceleration = -g;
  }

  let tossState = "Rising";
  if (t === 0) {
    tossState = "At launch";
  } else if (Math.abs(t - apexTime) < 0.001) {
    tossState = "At the top";
  } else if (t > apexTime) {
    tossState = t >= duration ? "At launch height" : "Falling";
  }

  let dropState = "Held in place";
  if (t >= apexTime) {
    if (Math.abs(t - apexTime) < 0.001) {
      dropState = "Just released";
    } else if (t >= duration) {
      dropState = "At launch height";
    } else {
      dropState = "Falling together";
    }
  }

  const laneY = 50;
  const laneW = 280;
  const laneH = 340;
  const tossLaneX = 25;
  const dropLaneX = 335;
  const axisOffsetY = 360;
  const axisH = 280;

  function toY(h) {
    return axisOffsetY - (h / 2.2) * axisH;
  }

  const objects = [];

  objects.push(...sdk.panel({
    id: "lane.toss",
    x: tossLaneX,
    y: laneY,
    w: laneW,
    h: laneH,
    title: "Toss Lane",
    state: tossState
  }));

  objects.push(...sdk.panel({
    id: "lane.drop",
    x: dropLaneX,
    y: laneY,
    w: laneW,
    h: laneH,
    title: "Drop Lane",
    state: dropState
  }));

  objects.push(sdk.axis("axis.toss", {
    x: tossLaneX + 45,
    y: axisOffsetY,
    length: axisH,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: 5,
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.axis("axis.drop", {
    x: dropLaneX + 45,
    y: axisOffsetY,
    length: axisH,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: 5,
    label: "Height",
    unit: "m"
  }));

  const gateY = toY(apexHeight);
  objects.push(...sdk.gate("gate", dropLaneX + 180, gateY, { open: gateOpen, w: 36, label: " apex" }));

  if (gateOpen) {
    objects.push(sdk.circle("outline.drop", dropLaneX + 180, gateY, 26, { opacity: 0.3, role: "neutral" }));
    objects.push(sdk.circle("outline.toss", tossLaneX + 180, gateY, 26, { opacity: 0.3, role: "neutral" }));
  }

  const tossY = toY(tossedHeight);
  const tossX = tossLaneX + 180;
  objects.push(sdk.circle("ball.toss", tossX, tossY, 28, { role: "learner" }));

  const vScale = 12;
  const aScale = 4;

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 22, y: tossY }, {
    value: tossedVelocity,
    direction: "up",
    scale: vScale,
    label: "v",
    role: "output"
  }));

  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 22, y: tossY }, {
    value: tossedAcceleration,
    direction: "up",
    scale: aScale,
    label: "a",
    role: "warning"
  }));

  objects.push(sdk.callout(tossX - 95, tossY - 14, [
    `v: ${sdk.format(tossedVelocity, 2)} m/s`,
    `a: ${sdk.format(tossedAcceleration, 2)} m/s²`
  ], { id: "callout.toss" }));

  const dropY = toY(dropHeight);
  const dropX = dropLaneX + 180;
  objects.push(sdk.circle("ball.drop", dropX, dropY, 28, { role: "tutor" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 22, y: dropY }, {
    value: dropVelocity,
    direction: "up",
    scale: vScale,
    label: "v",
    role: "output"
  }));

  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 22, y: dropY }, {
    value: dropAcceleration,
    direction: "up",
    scale: aScale,
    label: "a",
    role: "warning"
  }));

  objects.push(sdk.callout(dropX - 95, dropY - 14, [
    `v: ${sdk.format(dropVelocity, 2)} m/s`,
    `a: ${sdk.format(dropAcceleration, 2)} m/s²`
  ], { id: "callout.drop" }));

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    },
    readouts: [
      { id: "tossedVelocity", value: tossedVelocity },
      { id: "tossedAcceleration", value: tossedAcceleration },
      { id: "dropVelocity", value: dropVelocity },
      { id: "dropAcceleration", value: dropAcceleration }
    ]
  };
}
